{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * Build graph scheduler
 * Reads a build graph from stdin and supports three operations:
 * - waves: Group tasks by dependency depth
 * - explain: Show timing and depth for each task
 * - pack <workers>: Simulate execution on N workers
 */

import * as readline from 'readline'

class Graph {
  constructor() {
    this.tasks = new Map() // name -> { cost, dependencies: Set<name> }
    this.dependents = new Map() // name -> Set<names that depend on this>
  }

  addTask(name, cost, lineNum) {
    if (this.tasks.has(name)) {
      throw { code: 2, msg: `error: line ${lineNum}: task ${name} is declared twice` }
    }
    this.tasks.set(name, { cost, dependencies: new Set(), depth: -1 })
    if (!this.dependents.has(name)) {
      this.dependents.set(name, new Set())
    }
  }

  addDep(name, dep, lineNum) {
    if (!this.tasks.has(name)) {
      this.tasks.set(name, { cost: -1, dependencies: new Set(), depth: -1 })
    }
    if (!this.tasks.has(dep)) {
      this.tasks.set(dep, { cost: -1, dependencies: new Set(), depth: -1 })
    }

    this.tasks.get(name).dependencies.add(dep)
    if (!this.dependents.has(dep)) {
      this.dependents.set(dep, new Set())
    }
    this.dependents.get(dep).add(name)
  }

  validateTasks() {
    for (const [name, task] of this.tasks) {
      if (task.cost === -1) {
        throw { code: 2, msg: `error: unknown task ${name}` }
      }
    }
  }

  detectCycles() {
    const visited = new Set()
    const recursionStack = []
    const stackSet = new Set()

    const visit = (node) => {
      if (stackSet.has(node)) {
        // Found a cycle - find where it starts in the stack
        const cycleStart = recursionStack.indexOf(node)
        const cycle = recursionStack.slice(cycleStart)
        cycle.push(node)
        return cycle
      }

      if (visited.has(node)) {
        return null
      }

      visited.add(node)
      recursionStack.push(node)
      stackSet.add(node)

      // Visit dependencies in ascending order
      const deps = Array.from(this.tasks.get(node).dependencies).sort()
      for (const dep of deps) {
        const cycle = visit(dep)
        if (cycle) {
          return cycle
        }
      }

      recursionStack.pop()
      stackSet.delete(node)
      return null
    }

    // Check cycles starting from each task in ascending order
    const taskNames = Array.from(this.tasks.keys()).sort()
    for (const task of taskNames) {
      if (!visited.has(task)) {
        const cycle = visit(task)
        if (cycle) {
          return cycle
        }
      }
    }
    return null
  }

  calculateDepths() {
    const depths = new Map()

    const calcDepth = (name, visiting = new Set()) => {
      if (visiting.has(name)) {
        return -1 // Cycle detected
      }
      if (depths.has(name)) {
        return depths.get(name)
      }

      visiting.add(name)
      const deps = this.tasks.get(name).dependencies
      let maxDepth = -1

      if (deps.size === 0) {
        maxDepth = 0
      } else {
        for (const dep of deps) {
          const depDepth = calcDepth(dep, visiting)
          maxDepth = Math.max(maxDepth, depDepth + 1)
        }
      }

      visiting.delete(name)
      depths.set(name, maxDepth)
      return maxDepth
    }

    for (const name of this.tasks.keys()) {
      calcDepth(name)
    }

    return depths
  }

  calculateTimings(depths) {
    const timings = new Map() // name -> { start, finish }

    const calcTiming = (name, memo = new Map()) => {
      if (memo.has(name)) {
        return memo.get(name)
      }

      const task = this.tasks.get(name)
      let start = 0

      for (const dep of task.dependencies) {
        const depTiming = calcTiming(dep, memo)
        start = Math.max(start, depTiming.finish)
      }

      const finish = start + task.cost
      memo.set(name, { start, finish })
      return { start, finish }
    }

    for (const name of this.tasks.keys()) {
      const timing = calcTiming(name)
      timings.set(name, timing)
    }

    return timings
  }

  calculatePriorities() {
    // Priority = cost of longest chain from this task to any leaf
    const memo = new Map()

    const calcPriority = (name) => {
      if (memo.has(name)) {
        return memo.get(name)
      }

      const task = this.tasks.get(name)
      const dependents = Array.from(this.dependents.get(name) || [])

      if (dependents.length === 0) {
        memo.set(name, task.cost)
        return task.cost
      }

      let maxChain = 0
      for (const dependent of dependents) {
        maxChain = Math.max(maxChain, calcPriority(dependent))
      }

      const priority = task.cost + maxChain
      memo.set(name, priority)
      return priority
    }

    const priorities = new Map()
    for (const name of this.tasks.keys()) {
      priorities.set(name, calcPriority(name))
    }

    return priorities
  }
}

function parseInput(lines) {
  const graph = new Graph()
  const directives = []

  for (let i = 0; i < lines.length; i++) {
    let line = lines[i].trim()

    // Skip empty lines and comments
    if (!line || line.startsWith('#')) {
      continue
    }

    const parts = line.split(/\s+/)
    const directive = parts[0]
    const lineNum = i + 1

    if (directive === 'task') {
      if (parts.length !== 3) {
        throw { code: 2, msg: `error: line ${lineNum}: expected task <name> <cost>` }
      }

      const name = parts[1]
      const cost = parts[2]

      // Validate task name
      if (!/^[A-Za-z0-9_.\-]+$/.test(name)) {
        throw { code: 2, msg: `error: line ${lineNum}: invalid task name ${name}` }
      }

      // Validate cost
      if (!/^\d+$/.test(cost) || cost !== cost.replace(/^0+/, '') && cost.length > 1 && cost !== '0') {
        // Check for leading zeros (except for "0" itself)
        if (cost.length > 1 && cost[0] === '0') {
          throw { code: 2, msg: `error: line ${lineNum}: cost must be a non-negative integer` }
        }
      }

      if (!/^\d+$/.test(cost)) {
        throw { code: 2, msg: `error: line ${lineNum}: cost must be a non-negative integer` }
      }

      const costNum = parseInt(cost, 10)
      graph.addTask(name, costNum, lineNum)
    } else if (directive === 'dep') {
      if (parts.length < 2) {
        throw { code: 2, msg: `error: line ${lineNum}: expected dep <name> <dependency>...` }
      }

      const name = parts[0]
      const deps = parts.slice(2)

      // Validate that all deps exist and are valid names
      for (const dep of deps) {
        if (!/^[A-Za-z0-9_.\-]+$/.test(dep)) {
          throw { code: 2, msg: `error: line ${lineNum}: invalid task name ${dep}` }
        }
      }

      // Add dependencies (may create placeholder tasks)
      const depSet = new Set(deps)
      for (const dep of depSet) {
        graph.addDep(name, dep, lineNum)
      }
    } else {
      throw { code: 2, msg: `error: line ${lineNum}: unknown directive ${directive}` }
    }
  }

  // Validate that all referenced tasks are declared
  graph.validateTasks()

  // Check for cycles
  const cycle = graph.detectCycles()
  if (cycle) {
    const cycleStr = cycle.join(' -> ')
    throw { code: 3, msg: `error: cycle: ${cycleStr}` }
  }

  return graph
}

function parseArgs(argv) {
  if (argv.length === 0) {
    throw { code: 2, msg: 'error: usage: cli.js waves|explain|pack <workers>' }
  }

  const command = argv[0]

  if (command === 'waves' || command === 'explain') {
    if (argv.length !== 1) {
      throw { code: 2, msg: 'error: usage: cli.js waves|explain|pack <workers>' }
    }
    return { command }
  } else if (command === 'pack') {
    if (argv.length !== 2) {
      throw { code: 2, msg: 'error: usage: cli.js waves|explain|pack <workers>' }
    }

    const workers = argv[1]
    // Validate workers: must be positive integer, no sign, no leading zeros
    if (!/^\d+$/.test(workers)) {
      throw { code: 2, msg: 'error: workers must be a positive integer' }
    }

    const workersNum = parseInt(workers, 10)
    if (workersNum === 0 || (workers.length > 1 && workers[0] === '0')) {
      throw { code: 2, msg: 'error: workers must be a positive integer' }
    }

    return { command: 'pack', workers: workersNum }
  } else {
    throw { code: 2, msg: 'error: usage: cli.js waves|explain|pack <workers>' }
  }
}

function executeWaves(graph) {
  const depths = graph.calculateDepths()
  const timings = graph.calculateTimings(depths)

  // Group tasks by depth
  const waves = new Map()
  for (const [name, depth] of depths) {
    if (!waves.has(depth)) {
      waves.set(depth, [])
    }
    waves.get(depth).push(name)
  }

  // Sort each wave and output
  let maxFinish = 0
  const output = []

  const sortedDepths = Array.from(waves.keys()).sort((a, b) => a - b)
  for (const depth of sortedDepths) {
    const tasks = waves.get(depth).sort()
    output.push(`wave ${depth}: ${tasks.join(' ')}`)

    for (const task of tasks) {
      maxFinish = Math.max(maxFinish, timings.get(task).finish)
    }
  }

  output.push(`total ${maxFinish}`)
  return output.join('\n') + '\n'
}

function executeExplain(graph) {
  const depths = graph.calculateDepths()
  const timings = graph.calculateTimings(depths)

  const tasks = Array.from(graph.tasks.keys()).sort()
  const output = []

  for (const name of tasks) {
    const timing = timings.get(name)
    const depth = depths.get(name)
    output.push(`${name} start=${timing.start} finish=${timing.finish} depth=${depth}`)
  }

  let maxFinish = 0
  for (const [name, timing] of timings) {
    maxFinish = Math.max(maxFinish, timing.finish)
  }

  output.push(`total ${maxFinish}`)
  return output.join('\n') + '\n'
}

function executePack(graph, workers) {
  const timings = graph.calculateTimings(graph.calculateDepths())
  const priorities = graph.calculatePriorities()

  // Track worker states
  const workerFree = Array(workers).fill(0) // Time when each worker becomes free
  const workerTasks = Array(workers).fill(null).map(() => []) // Tasks assigned to each worker

  // Track finished tasks
  const finished = new Map() // name -> finish time

  // Calculate which tasks are ready
  const isReady = (name) => {
    const deps = graph.tasks.get(name).dependencies
    for (const dep of deps) {
      if (!finished.has(dep)) {
        return false
      }
    }
    return true
  }

  // Process all tasks
  let remaining = new Set(graph.tasks.keys())

  while (remaining.size > 0) {
    // Find next instant where a worker becomes free
    let nextTime = Math.min(...workerFree)

    // Assign ready tasks to free workers
    let assigned = true
    while (assigned) {
      assigned = false

      // Find free workers in order
      for (let w = 0; w < workers; w++) {
        if (workerFree[w] === nextTime) {
          // Find the best ready task
          let bestTask = null
          let bestPriority = -1

          for (const task of remaining) {
            if (isReady(task)) {
              const taskPriority = priorities.get(task)
              if (taskPriority > bestPriority || 
                  (taskPriority === bestPriority && (bestTask === null || task < bestTask))) {
                bestTask = task
                bestPriority = taskPriority
              }
            }
          }

          if (bestTask) {
            // Assign task to worker
            const cost = graph.tasks.get(bestTask).cost
            const start = nextTime
            const finish = start + cost

            workerTasks[w].push({ name: bestTask, start, finish })
            workerFree[w] = finish
            finished.set(bestTask, finish)
            remaining.delete(bestTask)
            assigned = true
            break // Process next worker
          }
        }
      }
    }

    if (remaining.size === 0) break

    // Update nextTime to next worker free time
    nextTime = Math.min(...workerFree)
  }

  // Generate output
  const output = []
  let makespan = 0

  for (let w = 0; w < workers; w++) {
    let workerLine = `worker ${w}:`
    for (const task of workerTasks[w]) {
      workerLine += ` ${task.name}@${task.start}-${task.finish}`
      makespan = Math.max(makespan, task.finish)
    }
    output.push(workerLine)
  }

  output.push(`makespan ${makespan}`)
  return output.join('\n') + '\n'
}

async function main() {
  try {
    // Parse command line arguments
    const args = process.argv.slice(2)
    const { command, workers } = parseArgs(args)

    // Read input
    const rl = readline.createInterface({
      input: process.stdin,
      output: undefined,
      terminal: false,
    })

    const lines = []
    for await (const line of rl) {
      lines.push(line)
    }

    // Parse graph
    const graph = parseInput(lines)

    // Execute command
    let output
    if (command === 'waves') {
      output = executeWaves(graph)
    } else if (command === 'explain') {
      output = executeExplain(graph)
    } else if (command === 'pack') {
      output = executePack(graph, workers)
    }

    process.stdout.write(output)
    process.exit(0)
  } catch (err) {
    if (err.code === 3) {
      process.stderr.write(err.msg + '\n')
      process.exit(3)
    } else if (err.code === 2) {
      process.stderr.write(err.msg + '\n')
      process.exit(2)
    } else {
      process.stderr.write(String(err) + '\n')
      process.exit(1)
    }
  }
}

main()
