  let maxFinish = 0
  const output = []

  const sortedDepths = Array.from(waves.keys()).sort((a, b) => a - b)
  for (const depth of sortedDepths) {
    const tasks = waves.get(depth).sort()
    output.push(`wave ${depth}: ${tasks.join(' ')}`)

    for (const task of tasks) {
      maxFinish = Math.max(maxFinish, timings.get(task).finish)
    }
  }

  output.push(`total ${maxFinish}`)
  return output.join('\n') + '\n'
}

